#include "stdlib/blas/ext/base/dcombinations.h"
#include "stdlib/blas/ext/base/dfill.h"
#include "stdlib/blas/ext/base/dzero_to.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/math/base/special/binomcoef.h"
#include <stdbool.h>
#include <stdint.h>


// MAIN //

/**
* Computes combinations of a specified length from double-precision floating-point strided array elements.
*
* @param order       storage layout
* @param N           number of indexed elements
* @param k           number of elements to combine
* @param replacement boolean indicating whether to allow duplication in combination
* @param X           input array
* @param strideX     stride length for X
* @param Out         output array
* @param LDO         stride length between successive contiguous vectors of the matrix Out (a.k.a., leading dimension of Out)
* @param Workspace   workspace array
* @param strideW     stride length for Workspace
*/
void API_SUFFIX(stdlib_strided_dcombinations)( const CBLAS_LAYOUT order, const CBLAS_INT N, const CBLAS_INT k, const bool replacement, const double *X, const CBLAS_INT strideX, double *Out, const CBLAS_INT LDO, double *Workspace, const CBLAS_INT strideW ) {
	CBLAS_INT so1;
	CBLAS_INT so2;
	int64_t ox;
	int64_t ow;

	if ( order == CblasColMajor ) {
		so1 = 1;
		so2 = LDO;
	} else { // order == CblasRowMajor
		so1 = LDO;
		so2 = 1;
	}
	ox = (int64_t)stdlib_strided_stride2offset( N, strideX );
	ow = (int64_t)stdlib_strided_stride2offset( k, strideW );
	API_SUFFIX(stdlib_strided_dcombinations_ndarray)( N, k, replacement, X, strideX, ox, Out, so1, so2, 0, Workspace, strideW, ow );
}

/**
* Computes combinations of a specified length from double-precision floating-point strided array elements using alternative indexing semantics.
*
* @param N           number of indexed elements
* @param k           number of elements to combine
* @param replacement boolean indicating whether to allow duplication in combination
* @param X           input array
* @param strideX     stride length for X
* @param offsetX     starting index for X
* @param Out         output array
* @param strideOut1  stride length for the first dimension of Out
* @param strideOut2  stride length for the second dimension of Out
* @param offsetOut   starting index for Out
* @param Workspace   workspace array
* @param strideW     stride length for Workspace
* @param offsetW     starting index for Workspace
*/
void API_SUFFIX(stdlib_strided_dcombinations_ndarray)( const CBLAS_INT N, const CBLAS_INT k, const bool replacement, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, double *Out, const CBLAS_INT strideOut1, const CBLAS_INT strideOut2, const CBLAS_INT offsetOut, double *Workspace, const CBLAS_INT strideW, const CBLAS_INT offsetW ) {
	double val;
	CBLAS_INT io;
	CBLAS_INT iw;
	CBLAS_INT oj;
	CBLAS_INT i;
	CBLAS_INT j;
	int64_t C;
	int64_t c;

	if ( N <= 0 || k <= 0 ) {
		return;
	}
	if ( !replacement && k > N ) {
		return;
	}

	// Compute the total number of combinations:
	if ( replacement ) {
		C = (int64_t)stdlib_base_binomcoef( N + k - 1, k );
	} else {
		C = (int64_t)stdlib_base_binomcoef( N, k );
	}
	// Initialize the workspace with the indices of the first combination:
	if ( replacement ) {
		API_SUFFIX(stdlib_strided_dfill_ndarray)( k, 0.0, Workspace, strideW, offsetW );
	} else {
		API_SUFFIX(stdlib_strided_dzero_to_ndarray)( k, Workspace, strideW, offsetW );
	}
	io = offsetOut;
	for ( c = 0; c < C; c++ ) {
		// Resolve the current combination's indices to input array values and write them to the output array:
		iw = offsetW;
		oj = io;
		for ( j = 0; j < k; j++ ) {
			Out[ oj ] = X[ offsetX + ( (CBLAS_INT)Workspace[ iw ] * strideX ) ];
			oj += strideOut2;
			iw += strideW;
		}
		io += strideOut1;

		// Advance to the next combination, starting from the rightmost index:
		iw = offsetW + ( ( k-1 ) * strideW );
		j = k - 1;
		if ( replacement ) {
			// Find the rightmost index that can be incremented:
			while ( j >= 0 && Workspace[ iw ] == N - 1 ) {
				j -= 1;
				iw -= strideW;
			}
			if ( j >= 0 ) {
				val = Workspace[ iw ] + 1;
				for ( i = j; i < k; i++ ) {
					Workspace[ iw ] = val;
					iw += strideW;
				}
			}
		} else {
			// Find the rightmost index that can be incremented:
			while ( j >= 0 && Workspace[ iw ] == N - k + j ) {
				j -= 1;
				iw -= strideW;
			}
			if ( j >= 0 ) {
				Workspace[ iw ] += 1;
				val = Workspace[ iw ];
				for ( i = j + 1; i < k; i++ ) {
					iw += strideW;
					val += 1;
					Workspace[ iw ] = val;
				}
			}
		}
	}
}
